int score = 78;
if (score >= 60) {
    System.out.println("Pass");
} else {
    System.out.println("Fail");
}

int grade = 85;
if (grade >= 90) {
    System.out.println("A");
} else if (grade >= 80) {
    System.out.println("B");
} else if (grade >= 70) {
    System.out.println("C");
} else {
    System.out.println("D or F");
}

int i = 1;
while (i <= 5) {
    System.out.println("Count: " + i);
    i++;
}

for (int j = 0; j < 5; j++) {
    System.out.println("Iteration " + j);
}

